head.b:skin:
/* ============================================================
   AURIX — Skull AI Studio · design system
   Dark navy / charcoal · orange + violet accents · RTL-aware
   ============================================================ */
:root{
  --bg:#0b1020; --bg2:#0d1226; --surface:#141a2e; --surface2:#1a2138;
  --line:#232c48; --line2:#2d3757;
  --text:#e8eaf2; --muted:#9aa3bd; --muted2:#6b7492;
  --orange:#ff7a1a; --orange2:#ff9440; --violet:#8b5cf6; --violet2:#a78bfa;
  --ok:#34d399; --warn:#fbbf24; --err:#f87171;
  --grad:linear-gradient(135deg,#ff7a1a 0%,#8b5cf6 100%);
  --radius:14px; --radius-sm:10px;
  --shadow:0 10px 30px rgba(2,6,20,.45);
  --side-w:248px;
  --ff:"Segoe UI",system-ui,-apple-system,Roboto,"Helvetica Neue",Arial,sans-serif;
  --fm:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;
}
*{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
body{background:var(--bg);color:var(--text);font-family:var(--ff);font-size:15.5px;line-height:1.6;-webkit-font-smoothing:antialiased;min-height:100vh}
img{max-width:100%;display:block}
a{color:var(--violet2);text-decoration:none}
a:hover{color:var(--orange2)}
button{font-family:inherit;cursor:pointer}
input,textarea,select{font-family:inherit;font-size:15px}
[hidden]{display:none!important}
.skip-link{position:absolute;left:-9999px;top:0;background:var(--orange);color:#0b1020;padding:8px 14px;border-radius:0 0 10px 0;z-index:200;font-weight:700}
.skip-link:focus{left:0}
::selection{background:rgba(139,92,246,.4)}
:focus-visible{outline:2px solid var(--orange);outline-offset:2px}
::-webkit-scrollbar{width:10px;height:10px}
::-webkit-scrollbar-thumb{background:var(--line2);border-radius:8px}
::-webkit-scrollbar-track{background:transparent}

/* ---------- shell ---------- */
.aurix-shell{display:flex;min-height:100vh}
.aurix-side{width:var(--side-w);flex:0 0 var(--side-w);background:var(--bg2);border-inline-end:1px solid var(--line);position:fixed;inset-block:0;inset-inline-start:0;z-index:100;display:flex;flex-direction:column;overflow-y:auto;transition:transform .22s ease}
.aurix-wrap{margin-inline-start:var(--side-w);flex:1;min-width:0;display:flex;flex-direction:column;min-height:100vh}
.aurix-top{position:sticky;top:0;z-index:90;background:rgba(11,16,32,.86);backdrop-filter:blur(10px);border-bottom:1px solid var(--line);display:flex;align-items:center;gap:12px;padding:10px 20px;min-height:58px}
.aurix-main{flex:1;padding:26px clamp(16px,4vw,44px) 60px;max-width:1180px;width:100%;margin:0 auto}

/* brand */
.brand{display:flex;align-items:center;gap:11px;padding:16px 18px;border-bottom:1px solid var(--line)}
.brand .logo{width:40px;height:40px;flex:0 0 40px;filter:drop-shadow(0 0 12px rgba(255,122,26,.35))}
.brand b{font-size:19px;letter-spacing:2.5px;font-weight:800}
.brand small{display:block;color:var(--muted2);font-size:10.5px;letter-spacing:1.6px;text-transform:uppercase}
.brand .bname{display:flex;flex-direction:column;line-height:1.25}

/* nav */
.nav{padding:12px 10px;display:flex;flex-direction:column;gap:2px;flex:1}
.nav .grp{color:var(--muted2);font-size:10.5px;letter-spacing:1.8px;text-transform:uppercase;padding:14px 10px 6px;font-weight:700}
.nav a{display:flex;align-items:center;gap:11px;padding:9px 12px;border-radius:var(--radius-sm);color:var(--muted);font-weight:600;font-size:14px;transition:background .15s,color .15s}
.nav a svg{width:19px;height:19px;flex:0 0 19px;opacity:.85}
.nav a:hover{background:var(--surface);color:var(--text)}
.nav a.active{background:linear-gradient(90deg,rgba(255,122,26,.14),rgba(139,92,246,.14));color:var(--text);box-shadow:inset 3px 0 0 var(--orange)}
[dir=rtl] .nav a.active{box-shadow:inset -3px 0 0 var(--orange)}
.nav a .badge{margin-inline-start:auto;font-size:10px;background:var(--violet);color:#fff;border-radius:20px;padding:1px 8px;font-weight:700}
.side-foot{padding:14px 18px;border-top:1px solid var(--line);color:var(--muted2);font-size:11.5px;line-height:1.5}

/* topbar */
.burger{display:none;background:var(--surface);border:1px solid var(--line2);color:var(--text);width:40px;height:40px;border-radius:10px;align-items:center;justify-content:center}
.top-title{font-weight:800;font-size:16px;letter-spacing:.4px;flex:1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.top-actions{display:flex;align-items:center;gap:8px}
.langs{display:flex;background:var(--surface);border:1px solid var(--line2);border-radius:10px;overflow:hidden}
.langs button{background:transparent;border:0;color:var(--muted);padding:8px 11px;font-weight:700;font-size:12.5px}
.langs button.active{background:var(--grad);color:#fff}
.backdrop{display:none;position:fixed;inset:0;background:rgba(4,7,18,.6);z-index:99}

/* ---------- generic UI ---------- */
.page-head{margin-bottom:22px}
.page-head h1{font-size:clamp(22px,3.4vw,30px);font-weight:800;letter-spacing:.3px;display:flex;align-items:center;gap:12px;flex-wrap:wrap}
.page-head h1 .ic{width:34px;height:34px;color:var(--orange)}
.page-head p{color:var(--muted);margin-top:6px;max-width:760px}
.card{background:var(--surface);border:1px solid var(--line);border-radius:var(--radius);padding:22px;box-shadow:var(--shadow)}
.card + .card{margin-top:18px}
.card h2{font-size:17px;font-weight:800;margin-bottom:14px;display:flex;align-items:center;gap:9px}
.card h2 svg{width:19px;height:19px;color:var(--violet2)}
.field{margin-bottom:15px}
.field label{display:block;font-size:12.5px;font-weight:700;color:var(--muted);margin-bottom:7px;letter-spacing:.4px}
.input,.ta,select.input{width:100%;background:var(--bg2);border:1px solid var(--line2);color:var(--text);border-radius:var(--radius-sm);padding:11px 13px;transition:border .15s}
.input:focus,.ta:focus,select.input:focus{border-color:var(--violet);outline:none;box-shadow:0 0 0 3px rgba(139,92,246,.18)}
.ta{min-height:120px;resize:vertical;line-height:1.55}
.chips{display:flex;flex-wrap:wrap;gap:8px}
.chip{background:var(--bg2);border:1px solid var(--line2);color:var(--muted);border-radius:30px;padding:7px 14px;font-size:13px;font-weight:600;transition:all .15s}
.chip:hover{border-color:var(--violet);color:var(--text)}
.chip.on{background:var(--grad);border-color:transparent;color:#fff;font-weight:700}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:9px;background:var(--grad);color:#fff;border:0;border-radius:var(--radius-sm);padding:12px 22px;font-size:15px;font-weight:800;letter-spacing:.3px;transition:transform .12s,box-shadow .15s;box-shadow:0 6px 20px rgba(255,122,26,.25)}
.btn:hover{transform:translateY(-1px);box-shadow:0 9px 26px rgba(139,92,246,.35)}
.btn:disabled{opacity:.5;cursor:not-allowed;transform:none}
.btn.ghost{background:var(--surface2);border:1px solid var(--line2);color:var(--text);box-shadow:none}
.btn.ghost:hover{border-color:var(--violet)}
.btn.sm{padding:8px 14px;font-size:13px}
.btn svg{width:17px;height:17px}
.row{display:flex;gap:10px;flex-wrap:wrap;align-items:center}
.hint{font-size:12.5px;color:var(--muted2);margin-top:8px;line-height:1.5}
.hint b{color:var(--muted)}
.note{border-radius:var(--radius-sm);padding:12px 15px;font-size:13.5px;line-height:1.55;border:1px solid}
.note.info{background:rgba(139,92,246,.09);border-color:rgba(139,92,246,.35);color:#cfc4f7}
.note.warn{background:rgba(251,191,36,.08);border-color:rgba(251,191,36,.35);color:#fde9b0}
.note.err{background:rgba(248,113,113,.08);border-color:rgba(248,113,113,.4);color:#fecaca}
.note.ok{background:rgba(52,211,153,.08);border-color:rgba(52,211,153,.35);color:#b8f5dd}

/* states */
.spinner{width:22px;height:22px;border:3px solid var(--line2);border-top-color:var(--orange);border-radius:50%;animation:spin .8s linear infinite;flex:0 0 22px}
@keyframes spin{to{transform:rotate(360deg)}}
.state{display:flex;gap:13px;align-items:flex-start;padding:15px;border-radius:var(--radius-sm);margin-top:14px}
.state.loading{background:rgba(255,122,26,.07);border:1px solid rgba(255,122,26,.25)}
.state.error{background:rgba(248,113,113,.08);border:1px solid rgba(248,113,113,.35)}
.state .msg{font-size:14px}
.state .msg b{display:block;margin-bottom:2px}
.pulse{animation:pulse 1.6s ease-in-out infinite}
@keyframes pulse{0%,100%{opacity:1}50%{opacity:.45}}
.empty{padding:44px 20px;text-align:center;color:var(--muted2);border:1.5px dashed var(--line2);border-radius:var(--radius)}
.empty svg{width:44px;height:44px;margin:0 auto 12px;opacity:.5}
.empty b{color:var(--muted);display:block;font-size:15px;margin-bottom:4px}

/* rate ring */
.ratebox{display:flex;align-items:center;gap:10px;margin-top:12px;font-size:12.5px;color:var(--muted)}
.ratering{width:30px;height:30px;position:relative;flex:0 0 30px}
.ratering svg{transform:rotate(-90deg)}
.ratering .bgc{stroke:var(--line2)}
.ratering .fgc{stroke:var(--orange);transition:stroke-dashoffset 1s linear}

/* ---------- landing ---------- */
.hero{position:relative;overflow:hidden;border:1px solid var(--line);border-radius:20px;background:radial-gradient(1200px 500px at 85% -10%,rgba(139,92,246,.16),transparent 60%),radial-gradient(900px 420px at -10% 110%,rgba(255,122,26,.13),transparent 55%),var(--surface);padding:clamp(34px,6vw,72px) clamp(22px,5vw,64px);text-align:center}
.hero .skull{width:clamp(88px,13vw,132px);margin:0 auto 20px;filter:drop-shadow(0 0 34px rgba(255,122,26,.45))}
.hero h1{font-size:clamp(34px,6.4vw,62px);font-weight:900;letter-spacing:6px;margin-bottom:10px}
.hero h1 span{background:var(--grad);-webkit-background-clip:text;background-clip:text;color:transparent}
.hero .tag{font-size:clamp(15px,2.2vw,19px);color:var(--muted);letter-spacing:2.5px;text-transform:uppercase;font-weight:600}
.hero .sub{max-width:640px;margin:16px auto 26px;color:var(--muted)}
.hero .cta{display:flex;gap:12px;justify-content:center;flex-wrap:wrap}
.tools-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:16px;margin-top:18px}
.tool-card{position:relative;display:block;background:var(--surface);border:1px solid var(--line);border-radius:var(--radius);padding:22px;transition:transform .15s,border .15s,box-shadow .15s;color:var(--text)}
.tool-card:hover{transform:translateY(-3px);border-color:var(--line2);box-shadow:var(--shadow)}
.tool-card .ic{width:46px;height:46px;border-radius:13px;display:flex;align-items:center;justify-content:center;background:rgba(255,122,26,.12);color:var(--orange);margin-bottom:14px}
.tool-card.v .ic{background:rgba(139,92,246,.14);color:var(--violet2)}
.tool-card b{font-size:16.5px;display:block;margin-bottom:5px}
.tool-card p{color:var(--muted);font-size:13.5px;line-height:1.5}
.tool-card .flag{position:absolute;top:14px;inset-inline-end:14px;font-size:10.5px;font-weight:800;letter-spacing:.8px;text-transform:uppercase;background:var(--surface2);border:1px solid var(--line2);color:var(--muted);padding:3px 9px;border-radius:20px}
.tool-card .flag.off{color:var(--warn);border-color:rgba(251,191,36,.4)}
.feat-strip{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:14px;margin-top:18px}
.feat{background:var(--surface);border:1px solid var(--line);border-radius:var(--radius);padding:16px 18px;display:flex;gap:12px;align-items:flex-start}
.feat svg{width:22px;height:22px;color:var(--violet2);flex:0 0 22px;margin-top:2px}
.feat b{display:block;font-size:14px;margin-bottom:2px}
.feat p{color:var(--muted);font-size:12.5px;line-height:1.5}

/* ---------- image studio ---------- */
.img-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:14px;margin-top:16px}
.img-card{background:var(--surface);border:1px solid var(--line);border-radius:var(--radius);overflow:hidden;position:relative}
.img-card img{width:100%;aspect-ratio:1/1;object-fit:cover;background:var(--bg2)}
.img-card .bar{display:flex;gap:6px;padding:9px 11px;align-items:center}
.img-card .bar .ttl{flex:1;font-size:11.5px;color:var(--muted2);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.icon-btn{background:var(--surface2);border:1px solid var(--line2);color:var(--muted);width:33px;height:33px;border-radius:9px;display:inline-flex;align-items:center;justify-content:center;transition:all .14s}
.icon-btn:hover{color:var(--text);border-color:var(--violet)}
.icon-btn.fav.on{color:var(--orange);border-color:rgba(255,122,26,.5);background:rgba(255,122,26,.12)}
.icon-btn svg{width:16px;height:16px}
.result-frame{margin-top:16px;border:1px solid var(--line);border-radius:var(--radius);background:var(--bg2);padding:14px;text-align:center}
.result-frame img{max-width:min(560px,100%);margin:0 auto;border-radius:10px;box-shadow:var(--shadow)}
.result-frame .meta{color:var(--muted2);font-size:12px;margin-top:9px}
.ratio-preview{display:inline-block;border:2px solid var(--line2);border-radius:5px;background:var(--surface2);vertical-align:middle}

/* ---------- code studio ---------- */
.code-out{background:#0a0e1d;border:1px solid var(--line);border-radius:var(--radius-sm);overflow:auto;max-height:460px;margin-top:14px}
.code-out pre{padding:16px;font-family:var(--fm);font-size:13px;line-height:1.6;tab-size:2}
.code-out code{font-family:var(--fm)}
.tk-kw{color:#c792ea}.tk-str{color:#c3e88d}.tk-com{color:#5c6a92;font-style:italic}.tk-num{color:#f78c6c}.tk-tag{color:#ff8a9d}.tk-attr{color:#ffcb6b}.tk-fn{color:#82aaff}
.preview-frame{width:100%;height:340px;border:1px solid var(--line2);border-radius:var(--radius-sm);background:#fff;margin-top:12px}
.out-head{display:flex;align-items:center;gap:10px;margin-top:16px;flex-wrap:wrap}
.out-head h3{font-size:14.5px;flex:1;min-width:140px}

/* ---------- writer ---------- */
.tools-list{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:10px}
.tool-opt{text-align:start;background:var(--bg2);border:1px solid var(--line2);border-radius:var(--radius-sm);padding:13px 14px;color:var(--text);transition:all .14s}
.tool-opt:hover{border-color:var(--violet)}
.tool-opt.on{border-color:var(--orange);background:rgba(255,122,26,.1)}
.tool-opt b{display:block;font-size:13.5px;margin-bottom:2px}
.tool-opt small{color:var(--muted2);font-size:11.5px;line-height:1.4;display:block}
.writer-out{background:#0a0e1d;border:1px solid var(--line);border-radius:var(--radius-sm);padding:18px;margin-top:14px;white-space:pre-wrap;line-height:1.7;font-size:14.5px;max-height:520px;overflow:auto}

/* ---------- history / projects ---------- */
.hist-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:13px;margin-top:14px}
.hist-card{background:var(--surface);border:1px solid var(--line);border-radius:var(--radius);padding:15px;display:flex;flex-direction:column;gap:9px}
.hist-card .thumb{border-radius:8px;overflow:hidden;background:var(--bg2);max-height:130px}
.hist-card .thumb img{width:100%;height:130px;object-fit:cover}
.hist-card .kind{font-size:10px;font-weight:800;letter-spacing:1px;text-transform:uppercase;color:var(--violet2)}
.hist-card .kind.k-image{color:var(--orange2)}
.hist-card .kind.k-code{color:#82aaff}
.hist-card p{font-size:13px;color:var(--muted);display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.hist-card time{font-size:11px;color:var(--muted2)}
.proj-folders{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:13px;margin-top:14px}

/* ---------- settings ---------- */
.set-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:14px}
.set-tile{background:var(--bg2);border:1px solid var(--line2);border-radius:var(--radius-sm);padding:16px}
.set-tile b{display:block;margin-bottom:4px;font-size:14px}
.set-tile p{color:var(--muted);font-size:12.5px;margin-bottom:10px;line-height:1.5}

/* ---------- info pages ---------- */
.aurix-page{max-width:840px;margin:0 auto}
.aurix-page h1{font-size:clamp(24px,3.6vw,34px);font-weight:800;margin-bottom:18px}
.aurix-page .content{color:var(--muted);line-height:1.75}
.aurix-page .content h2{color:var(--text);font-size:19px;margin:26px 0 10px}
.aurix-page .content h3{color:var(--text);font-size:16px;margin:20px 0 8px}
.aurix-page .content p{margin-bottom:13px}
.aurix-page .content ul{margin:0 0 13px;padding-inline-start:22px}
.aurix-page .content li{margin-bottom:7px}
.aurix-page .content b,.aurix-page .content strong{color:var(--text)}

/* toast */
.toasts{position:fixed;bottom:18px;inset-inline-end:18px;z-index:300;display:flex;flex-direction:column;gap:9px}
.toast{background:var(--surface2);border:1px solid var(--line2);border-inline-start:4px solid var(--orange);color:var(--text);padding:12px 16px;border-radius:10px;font-size:13.5px;box-shadow:var(--shadow);max-width:340px;animation:tin .25s ease}
.toast.ok{border-inline-start-color:var(--ok)}
.toast.err{border-inline-start-color:var(--err)}
@keyframes tin{from{transform:translateY(8px);opacity:0}to{transform:none;opacity:1}}

/* footer */
.aurix-foot{border-top:1px solid var(--line);padding:22px clamp(16px,4vw,44px);color:var(--muted2);font-size:12.5px;text-align:center}

/* ads placeholders — hidden until an ad network approves the site */
.ad-slot{display:none}

/* ---------- responsive ---------- */
@media (max-width:1023px){
  .aurix-side{transform:translateX(-105%)}
  [dir=rtl] .aurix-side{transform:translateX(105%)}
  .aurix-side.open{transform:none}
  .aurix-wrap{margin-inline-start:0}
  .burger{display:inline-flex}
  .backdrop.show{display:block}
}
@media (max-width:560px){
  body{font-size:15px}
  .aurix-main{padding:18px 14px 50px}
  .card{padding:16px}
  .hero .cta .btn{width:100%}
}
@media (prefers-reduced-motion:reduce){
  *{animation-duration:.01ms!important;transition-duration:.01ms!important}
}

/* ---------- AURIX welcome / Google sign-in (original brand identity) ---------- */
body.auth-mode{background:#faf9f8;color:#17151a}
body.auth-mode .aurix-side,body.auth-mode .aurix-top,body.auth-mode .aurix-foot,body.auth-mode .backdrop{display:none!important}
body.auth-mode .aurix-wrap{margin-inline-start:0}
body.auth-mode .aurix-main{padding:0;max-width:none;margin:0;width:100%;min-height:100svh}
body.auth-mode .skip-link{background:#17151a;color:#fff}
.auth-screen{min-height:100svh;background:radial-gradient(700px 470px at 95% -30%,rgba(139,92,246,.08),transparent),#faf9f8;padding:clamp(22px,4vw,42px) 24px max(28px,env(safe-area-inset-bottom));display:flex;align-items:center;justify-content:center}
.auth-panel{width:min(100%,530px);min-height:min(780px,calc(100svh - 48px));display:flex;flex-direction:column}
.auth-head{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:clamp(42px,8vh,92px)}
.auth-brand{display:flex;align-items:center;gap:11px;color:#18151e;font-weight:900;letter-spacing:3px;font-size:22px}
.auth-brand img{width:46px;height:46px;border-radius:12px;object-fit:cover;background:#0b1020}
.auth-head .auth-langs{display:flex;gap:2px;background:#efebed;padding:3px;border-radius:12px}
.auth-head .auth-langs button{border:0;background:transparent;color:#6a6470;font-size:12px;font-weight:800;border-radius:9px;padding:7px 9px}
.auth-head .auth-langs button.active{background:#fff;color:#1d1822;box-shadow:0 1px 5px rgba(15,15,25,.12)}
.auth-intro h1{font-size:clamp(34px,6vw,48px);line-height:1.15;letter-spacing:-1.5px;font-weight:800;color:#17151a;margin-bottom:16px}
.auth-intro h1 em{font-style:normal;background:linear-gradient(115deg,#ef6b1c 10%,#8254e7 90%);-webkit-background-clip:text;background-clip:text;color:transparent}
.auth-intro>p{font-size:clamp(17px,2.2vw,20px);line-height:1.48;color:#4d4851;margin-bottom:32px;max-width:490px}
.auth-facts{border-top:1px solid #e7e4e6}
.auth-fact{display:grid;grid-template-columns:28px 1fr;gap:16px;padding:22px 0;border-bottom:1px solid #e7e4e6}
[dir=rtl] .auth-fact{grid-template-columns:28px 1fr}
.auth-fact svg{width:25px;height:25px;color:#605964;stroke-width:1.8;margin-top:3px}
.auth-fact b{display:block;font-size:16px;line-height:1.3;margin-bottom:4px;color:#1f1b22}
.auth-fact p{font-size:15px;line-height:1.45;color:#55505a}
.auth-fact a,.auth-consent a{color:#30283d;text-decoration:underline;text-underline-offset:3px;font-weight:600}
.auth-actions{margin-top:auto;padding-top:50px}
.auth-consent{border:1px solid #ddd8de;border-radius:15px;background:#fff;padding:17px 19px;color:#4a434c;font-size:14px;line-height:1.55;margin-bottom:20px}
.auth-google{width:100%;height:55px;display:flex;align-items:center;justify-content:center;gap:12px;border-radius:999px;font-size:16px;font-weight:800;transition:transform .15s,box-shadow .15s}
.auth-google{background:#16131b;color:#fff;border:1px solid #16131b}
.auth-google:hover{background:#30283b;transform:translateY(-1px);box-shadow:0 8px 18px rgba(28,23,35,.16)}
.auth-google:disabled{opacity:.55;cursor:not-allowed;transform:none}
.auth-google svg{width:23px;height:23px}
.auth-status{color:#ae2d36;font-size:13px;line-height:1.5;min-height:20px;margin:10px 0 2px;text-align:center}
.auth-hint{text-align:center;font-size:12px;color:#756e79;margin-top:18px;line-height:1.45}
.auth-hint span{display:block}
@media(max-width:560px){
  .auth-screen{padding:22px 24px max(22px,env(safe-area-inset-bottom));align-items:stretch}
  .auth-panel{min-height:calc(100svh - 44px)}
  .auth-head{margin-bottom:clamp(35px,6vh,68px)}
  .auth-intro h1{font-size:clamp(32px,8vw,39px)}
  .auth-fact{padding:18px 0}
  .auth-actions{padding-top:32px}
}
.auth-google-mark{font-family:Arial,sans-serif;font-weight:900;font-size:27px;line-height:1;background:conic-gradient(from 50deg,#4285f4 0 25%,#34a853 25% 50%,#fbbc05 50% 73%,#ea4335 73% 88%,#4285f4 88%);-webkit-background-clip:text;background-clip:text;color:transparent}
/* AURIX conversation: real answers, local PDF reading */
.sr-only{position:absolute!important;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.chat-box{max-width:830px;margin:0 auto;background:var(--surface);border:1px solid var(--line);border-radius:var(--radius);padding:20px;box-shadow:var(--shadow)}
.chat-top{display:flex;align-items:center;justify-content:space-between;gap:12px;padding-bottom:16px;border-bottom:1px solid var(--line)}
.chat-top b{font-size:18px;color:var(--text)}
.chat-messages{min-height:260px;max-height:55svh;overflow:auto;display:flex;flex-direction:column;gap:16px;padding:22px 4px;scroll-behavior:smooth}
.chat-empty{color:var(--muted);text-align:center;margin:auto;max-width:410px;line-height:1.65}
.chat-empty b{display:block;color:var(--text);font-size:19px;margin-bottom:8px}
.chat-line{max-width:min(92%,620px);padding:15px 18px;border:1px solid var(--line);border-radius:18px;background:var(--surface2);overflow-wrap:anywhere}
.chat-line.user{align-self:flex-end;background:rgba(137,78,225,.18);border-color:rgba(148,95,223,.4)}
.chat-line.assistant{align-self:flex-start}
.chat-line b{display:block;font-size:12px;margin-bottom:6px;color:var(--muted)}
.chat-line p{white-space:pre-wrap;line-height:1.65;color:var(--text)}
.chat-attachment{padding:10px 12px;color:var(--muted);background:var(--surface2);border:1px solid var(--line);border-radius:12px;font-size:12px;line-height:1.6;margin-bottom:12px}
.chat-attachment button{background:transparent;border:0;color:var(--accent);font-weight:700;text-decoration:underline;margin-inline-start:8px}
.chat-actions{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:12px 0}
.chat-attach{cursor:pointer}
@media(max-width:600px){.chat-box{padding:15px}.chat-messages{min-height:240px;max-height:52svh}.chat-top .badge{font-size:10px}.chat-line{max-width:96%}}

/* Public, crawlable guides remain accessible without bypassing Google-only tools. */
.auth-public-links{margin-top:22px;padding-top:16px;border-top:1px solid #dedbe5;font-size:13px;line-height:1.7;color:#514c5f}.auth-public-links b{display:block;color:#17151a;font-size:14px}.auth-public-links p{margin:4px 0 9px}.auth-public-links a{display:inline-block;margin-inline-end:13px;color:#5e2fa8;text-decoration:underline}.seo-fallback{max-width:760px;margin:auto;padding:70px 24px;line-height:1.75}.seo-fallback a{color:var(--orange)}

.public-page-nav{display:block;line-height:2;margin:0 0 20px;color:var(--muted)}.public-page-nav a,.public-page-footer a{color:var(--orange)}.public-page-footer{padding:20px 0;color:var(--muted);font-size:13px}.seo-fallback nav a{display:inline-block;margin-inline-end:8px}

/* 2026 AURIX brand polish: consistent icon rhythm, mobile-first spacing */
.aurix-side{background:linear-gradient(180deg,#11162a 0%,#0d1223 100%)}
.brand{min-height:77px;gap:12px}
.brand .logo{width:44px;height:44px;flex:0 0 44px;border-radius:12px;object-fit:cover}
.nav{gap:3px;padding:14px 10px}
.nav .grp{padding:17px 12px 7px}
.nav a{min-height:44px;gap:12px;padding:9px 12px;line-height:1.3}
.nav .nav-icon{width:20px;height:20px;flex:0 0 20px;opacity:.85;display:block}
.nav a.active .nav-icon{color:var(--orange);opacity:1}
.nav a .badge{flex:none}
.hero{padding-block:clamp(30px,5vw,56px)}
.hero-eyebrow{color:var(--violet2);font-size:11px;font-weight:800;letter-spacing:2.4px;margin-bottom:15px}
.hero .skull{width:clamp(158px,23vw,220px);aspect-ratio:1;object-fit:contain;margin:0 auto 15px;border-radius:22px;filter:drop-shadow(0 10px 28px rgba(139,92,246,.18))}
.hero .hero-title{font-size:clamp(26px,4vw,40px);line-height:1.15;font-weight:900;letter-spacing:2px;margin:0 0 9px;color:var(--text)}
.hero .hero-title span{color:var(--orange2)}
.tool-card{min-height:177px;display:flex;flex-direction:column;align-items:flex-start;padding:23px}
.tool-card .ic{flex:0 0 48px;width:48px;height:48px;margin-bottom:16px}
.tool-card .ic .nav-icon{width:24px;height:24px;display:block}
.tool-card .flag{max-width:calc(100% - 100px);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.tool-card b,.tool-card p{max-width:100%}
@media(max-width:560px){
 .hero{padding:30px 18px}
 .hero .skull{width:clamp(150px,45vw,192px)}
 .hero-eyebrow{font-size:10px;letter-spacing:1.6px}
 .tools-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}
 .tool-card{min-height:170px;padding:14px}
 .tool-card .ic{width:40px;height:40px;flex-basis:40px;margin-bottom:12px}
 .tool-card .ic .nav-icon{width:21px;height:21px}
 .tool-card .flag{position:static;order:4;margin-top:auto;max-width:100%;font-size:9px}
 .tool-card b{font-size:14px}
 .tool-card p{font-size:12px;line-height:1.4;margin-bottom:8px}
 .aurix-top{padding:8px 12px;gap:8px}
 .top-title{font-size:14px}
 .langs button{padding:8px 8px}
 .auth-brand{gap:9px;font-size:19px;letter-spacing:1.5px}
 .auth-brand img{width:44px;height:44px}
}
@media(max-width:360px){.tools-grid{grid-template-columns:1fr}.top-actions{gap:4px}.langs button{padding:7px 6px}}

.blogger-content{max-width:850px;margin:36px auto;padding:0 20px 70px}.blogger-content .post-outer{background:var(--surface);border:1px solid var(--line);padding:26px;border-radius:var(--radius)}.blogger-content .post-body{color:var(--muted);line-height:1.75}.blogger-content .post-body h2{color:var(--text);margin:20px 0 8px}.blogger-content .post-title{font-size:28px}.blogger-content .post-header,.blogger-content .post-footer{color:var(--muted2)}.blogger-back{display:inline-flex;margin-bottom:16px}

b:if.script:
/* AURIX — real-provider client with Google sign-in gate. No embedded API secrets. */
(function(){'use strict';
const API='https://aurix-api-ea09b.ahmedbecetti41.workers.dev';
const LS='aurix_v1_';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const safe=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tr={
 en:{home:'Home',chat:'AI Chat',image:'AI Image Studio',video:'AI Video Studio',code:'AI Code Studio',writer:'AI Writer',projects:'My Projects',history:'History',favorites:'Favorites',settings:'Profile & Settings',about:'About',contact:'Contact',privacy:'Privacy Policy',terms:'Terms of Service',create:'Create',recent:'Recent creations',saved:'Saved locally on this browser',unavailable:'Currently unavailable',generate:'Generate'},
 fr:{home:'Accueil',chat:'Discussion IA',image:'Studio Image IA',video:'Studio Vidéo IA',code:'Studio Code IA',writer:'Rédaction IA',projects:'Mes projets',history:'Historique',favorites:'Favoris',settings:'Profil et paramètres',about:'À propos',contact:'Contact',privacy:'Confidentialité',terms:"Conditions d'utilisation",create:'Créer',recent:'Créations récentes',saved:'Enregistré localement dans ce navigateur',unavailable:'Indisponible',generate:'Générer'},
 ar:{home:'الرئيسية',chat:'محادثة ذكية',image:'استوديو الصور',video:'استوديو الفيديو',code:'استوديو البرمجة',writer:'الكاتب الذكي',projects:'مشاريعي',history:'السجل',favorites:'المفضلة',settings:'الملف والإعدادات',about:'من نحن',contact:'اتصل بنا',privacy:'سياسة الخصوصية',terms:'شروط الاستخدام',create:'إنشاء',recent:'أحدث الإبداعات',saved:'محفوظ محليًا في هذا المتصفح',unavailable:'غير متاح حاليًا',generate:'توليد'}
};
const localCopy={
 fr:{'Tools connected to real providers':'Des outils qui fonctionnent','Start creating →':'Commencer →','Explore studios':'Explorer les studios','Real provider':'Vrai fournisseur','Not available':'Indisponible','Image Studio':"Studio d’images",'Code Studio':'Studio de code','Video Studio':'Studio vidéo','AI Writer':'Rédaction IA','No fabricated outputs':'Aucun faux résultat','Private by design':'Confidentialité intégrée','Free, best effort':'Gratuit, sans garantie','Describe your image':'Décrivez votre image','Optional visual direction · modifies the prompt (not a different model)':'Style visuel · ajouté au prompt (pas un autre modèle)','Aspect ratio':'Format','Generate image':'Créer une image','Image gallery':'Galerie d’images','No images yet':'Aucune image','Action':'Action','Language / format':'Langue / format','Describe what you need or paste code':'Décrivez votre demande ou collez du code','Ask AI':'Interroger l’IA','Choose an action':'Choisir une action','Topic, instructions, or source text':'Sujet, consignes ou texte source','Output language':'Langue de sortie','Generate text':'Générer un texte','Currently unavailable':'Indisponible pour le moment','New folder':'Nouveau dossier','Create folder':'Créer un dossier','Export your work':'Exporter vos travaux','Delete local data':'Supprimer les données locales','No history yet':'Aucun historique','No favorites':'Aucun favori'},
 ar:{'Tools connected to real providers':'أدوات تعمل بالفعل','Start creating →':'ابدأ الإبداع ←','Explore studios':'استكشف الاستوديوهات','Real provider':'مزود حقيقي','Not available':'غير متاح','Image Studio':'استوديو الصور','Code Studio':'استوديو البرمجة','Video Studio':'استوديو الفيديو','AI Writer':'الكاتب الذكي','No fabricated outputs':'لا نتائج وهمية','Private by design':'خصوصية من البداية','Free, best effort':'مجاني حسب التوفر','Describe your image':'صف الصورة التي تريدها','Optional visual direction · modifies the prompt (not a different model)':'النمط البصري · يضاف للوصف وليس نموذجًا منفصلًا','Aspect ratio':'نسبة الأبعاد','Generate image':'أنشئ صورة','Image gallery':'معرض الصور','No images yet':'لا توجد صور بعد','Action':'المهمة','Language / format':'اللغة / الصيغة','Describe what you need or paste code':'صف المطلوب أو الصق الشيفرة','Ask AI':'اسأل الذكاء الاصطناعي','Choose an action':'اختر المهمة','Topic, instructions, or source text':'الموضوع أو التعليمات أو النص الأصلي','Output language':'لغة النتيجة','Generate text':'أنشئ النص','Currently unavailable':'غير متاح حاليًا','New folder':'مجلد جديد','Create folder':'إنشاء مجلد','Export your work':'تصدير أعمالك','Delete local data':'حذف البيانات المحلية','No history yet':'لا يوجد سجل بعد','No favorites':'لا توجد مفضلة'}
};
function translateView(){if(lang==='en')return;const dict=localCopy[lang],w=document.createTreeWalker($('#view'),NodeFilter.SHOW_TEXT);while(w.nextNode()){let n=w.currentNode,k=n.nodeValue.trim();if(dict[k])n.nodeValue=n.nodeValue.replace(k,dict[k])}}
let lang=localStorage.getItem(LS+'lang')||'en', route='home', busy=false, activeJob=null;
let activeUserId=null,items=[],folders=['Unsorted'],cloudItems=[],chatMessages=[],chatPdf=null;
const key=(k)=>LS+(['items','folders','chat'].includes(k)?'user_'+(activeUserId||'locked')+'_':'')+k;
const PHOTO='aurix-image:';
let photoDbPromise=null;
const photoUrls=new Map();
function clearPhotoUrls(){for(const url of photoUrls.values())URL.revokeObjectURL(url);photoUrls.clear()}
function photoDB(){
 if(!photoDbPromise)photoDbPromise=new Promise((resolve,reject)=>{
  if(!window.indexedDB)return reject(Error('This browser does not support local image storage.'));
  const r=indexedDB.open('aurix-photos-v1',1);
  r.onupgradeneeded=()=>r.result.createObjectStore('photos');
  r.onsuccess=()=>resolve(r.result);
  r.onerror=()=>reject(r.error||Error('Image storage unavailable'));
 }).catch(e=>{photoDbPromise=null;throw e});
 return photoDbPromise;
}
async function photoPut(id,blob){
 const uid=activeUserId;if(!uid)throw Error('Sign in first.');const db=await photoDB();
 return new Promise((resolve,reject)=>{const tx=db.transaction('photos','readwrite');tx.objectStore('photos').put(blob,uid+':'+id);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error||Error('Image storage full'));tx.onabort=()=>reject(tx.error||Error('Image storage unavailable'))});
}
async function photoGet(id,uid=activeUserId){
 if(!uid)return null;const db=await photoDB();
 return new Promise((resolve,reject)=>{const r=db.transaction('photos').objectStore('photos').get(uid+':'+id);r.onsuccess=()=>resolve(r.result||null);r.onerror=()=>reject(r.error)});
}
async function photoDelete(id,uid=activeUserId){if(!uid)return;const db=await photoDB();return new Promise((resolve,reject)=>{const tx=db.transaction('photos','readwrite');tx.objectStore('photos').delete(uid+':'+id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
async function photoClear(uid){if(!uid)return;const db=await photoDB();return new Promise((resolve,reject)=>{const tx=db.transaction('photos','readwrite'),store=tx.objectStore('photos');store.openCursor().onsuccess=e=>{const cur=e.target.result;if(cur){if(String(cur.key).startsWith(uid+':'))cur.delete();cur.continue()}};tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
async function hydratePhotos(){
 const uid=activeUserId;if(!uid)return;
 for(const img of $$('img[data-photo-id]')){
  const id=img.dataset.photoId,k=uid+':'+id;
  try{if(!photoUrls.has(k)){const blob=await photoGet(id,uid);if(!blob)continue;photoUrls.set(k,URL.createObjectURL(blob))}
   if(activeUserId===uid&&img.isConnected)img.src=photoUrls.get(k);
  }catch{ /* Local storage may be unavailable; keep a visible placeholder. */ }
 }
}
function imageMarkup(o){return o.result?.startsWith(PHOTO)?`data-photo-id="${safe(o.id)}"`: `src="${safe(o.result)}"`}

function syncAccount(){const id=window.AurixCloud?.user?.uid||null;if(id===activeUserId)return;clearPhotoUrls();activeUserId=id;items=read('items',[]);folders=read('folders',['Unsorted']);chatMessages=read('chat',[]);chatPdf=null;cloudItems=[]}
function read(k,def){try{let x=JSON.parse(localStorage.getItem(key(k)));return x??def}catch{return def}}
function save(k,x){try{localStorage.setItem(key(k),JSON.stringify(x));return true}catch{toast('Browser storage is full or unavailable. Export your work.','err');return false}}
const t=(k)=>tr[lang]?.[k]||tr.en[k]||k;
function toast(msg,type=''){const n=document.createElement('div');n.className='toast '+type;n.textContent=msg;$('#toasts').append(n);setTimeout(()=>n.remove(),5500)}
function stamp(){return new Date().toISOString()}
function addItem(kind,prompt,result,meta={},fixedId=null){const o={id:fixedId||Date.now().toString(36)+Math.random().toString(36).slice(2,7),kind,prompt,result,meta,at:stamp(),fav:false,folder:'Unsorted'};items.unshift(o);items=items.slice(0,60);save('items',items);return o}
function toggleFav(id){let o=items.find(x=>x.id===id);if(o){o.fav=!o.fav;save('items',items);render()}}
function delItem(id){const old=items.find(x=>x.id===id);if(old?.result?.startsWith(PHOTO)){const uid=activeUserId,k=uid+':'+id;if(photoUrls.has(k)){URL.revokeObjectURL(photoUrls.get(k));photoUrls.delete(k)}photoDelete(id,uid).catch(()=>toast('Could not remove local image data.','err'))}items=items.filter(x=>x.id!==id);save('items',items);render()}
function fmt(d){try{return new Date(d).toLocaleString(lang)}catch{return d}}
function head(title,sub){return `<div class="page-head"><h1>${safe(title)}</h1>${sub?`<p>${sub}</p>`:''}</div>`}
function state(id){return `<div id="${id}" role="status" aria-live="polite"></div>`}
function showState(el,type,msg){el.className='state '+type;el.innerHTML=(type==='loading'?'<span class="spinner" aria-hidden="true"></span>':'')+'<div class="msg">'+safe(msg)+'</div>'}
function clearState(el){el.className='';el.textContent=''}
function nav(){const h=decodeURIComponent(location.hash.slice(1)).split('?')[0];if(h==='privacy'||h==='terms')return h;const signedIn=!!window.AurixCloud?.user;if(!signedIn)return 'login';return ['home','chat','image','video','code','writer','projects','history','favorites','settings','about','contact'].includes(h)?h:'home'}
function applyLang(){if(!tr[lang])lang='en';document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';$$('[data-i]').forEach(e=>e.textContent=t(e.dataset.i));$$('[data-lang]').forEach(e=>e.classList.toggle('active',e.dataset.lang===lang));}
function render(){syncAccount();if(activeJob){activeJob.controller.abort();clearTimeout(activeJob.timeout);clearInterval(activeJob.tick);activeJob=null}route=nav();applyLang();document.body.classList.toggle('auth-mode',route==='login');$('#top-title').textContent=t(route);$('#top-signin').hidden=route==='login';$('#top-signin').textContent=window.AurixCloud?.user?(lang==='ar'?'تسجيل الخروج':lang==='fr'?'Déconnexion':'Sign out'):(lang==='ar'?'تسجيل الدخول':lang==='fr'?'Connexion':'Sign in');$$('[data-route]').forEach(a=>{const active=a.dataset.route===route;a.classList.toggle('active',active);active?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current')});let view=$('#view');view.innerHTML=({login,home,chat,image,video,code,writer,projects,history,favorites,settings,about,contact,privacy,terms})[route]();$('#year').textContent=new Date().getFullYear();document.title=(route==='home'?'AURIX — Imagine. Create. Build.':route==='login'?'Welcome to AURIX — Sign in':t(route)+' — AURIX');$('#side').classList.remove('open');$('#backdrop').classList.remove('show');$('#burger').setAttribute('aria-expanded','false');busy=false;bindRoute();translateView();hydratePhotos();}
const authCopy={
 en:{welcome:'Welcome to',intro:'Turn your ideas into images, code and words. Sign in with Google to use the AURIX studio and save selected projects.',caution:'AI results need review',cautionText:'Images may miss details in your prompt. Check writing and code before relying on them.',privacy:'Your privacy, your choice',privacyText:'Prompts go to an external AI provider when you generate. Work saved locally stays on this device unless you choose to save it to your account.',choices:'Read your privacy choices',consent:'By continuing, you agree to the',terms:'Terms of Service',policy:'Privacy Policy',and:'and have read the',google:'Continue with Google',connecting:'Connecting to Google…',accountHint:'A Google account is required to enter. Cloud saving is optional.',cancel:'Google sign-in was cancelled. Try again to enter AURIX.',blocked:'Your browser blocked the Google window. Allow pop-ups for this site and retry.',unavailable:'Google sign-in is unavailable right now. Please try again later.'},
 fr:{welcome:'Bienvenue sur',intro:'Transformez vos idées en images, code et textes. Connectez-vous avec Google pour accéder à AURIX et sauvegarder vos projets.',caution:'Vérifiez les résultats de l’IA',cautionText:'Les images peuvent manquer des détails. Vérifiez les textes et le code avant de les utiliser.',privacy:'Votre vie privée, votre choix',privacyText:'Les demandes sont envoyées à un fournisseur d’IA lors de la génération. Vos créations locales restent sur cet appareil, sauf sauvegarde dans votre compte.',choices:'Lire les choix de confidentialité',consent:'En continuant, vous acceptez les',terms:'Conditions d’utilisation',policy:'Politique de confidentialité',and:'et avez lu notre',google:'Continuer avec Google',connecting:'Connexion à Google…',accountHint:'Un compte Google est nécessaire. La sauvegarde en ligne est facultative.',cancel:'Connexion Google annulée. Réessayez pour accéder à AURIX.',blocked:'La fenêtre Google a été bloquée. Autorisez les fenêtres contextuelles et réessayez.',unavailable:'Connexion Google indisponible. Réessayez plus tard.'},
 ar:{welcome:'مرحبًا بك في',intro:'حوّل أفكارك إلى صور وشيفرات ونصوص. سجّل الدخول بحساب Google لاستخدام AURIX وحفظ مشاريع تختارها.',caution:'راجع نتائج الذكاء الاصطناعي',cautionText:'قد لا تتبع الصور كل تفاصيل وصفك. تحقّق من النصوص والشيفرات قبل استخدامها.',privacy:'خصوصيتك بيدك',privacyText:'يُرسل وصفك إلى مزود ذكاء اصطناعي خارجي عند التوليد. تبقى الأعمال المحفوظة محليًا في جهازك إلا إذا اخترت حفظها في حسابك.',choices:'اقرأ خيارات الخصوصية',consent:'بالمتابعة، توافق على',terms:'شروط الاستخدام',policy:'سياسة الخصوصية',and:'وتقرّ بقراءة',google:'المتابعة عبر Google',connecting:'جارٍ الاتصال بـGoogle…',accountHint:'يجب تسجيل الدخول بحساب Google. الحفظ السحابي اختياري.',cancel:'أُلغيت عملية الدخول عبر Google. أعد المحاولة للدخول إلى AURIX.',blocked:'حظر المتصفح نافذة Google. اسمح بالنوافذ المنبثقة لهذا الموقع وأعد المحاولة.',unavailable:'تسجيل الدخول عبر Google غير متاح الآن. حاول لاحقًا.'}
};
function login(){
 const c=authCopy[lang]||authCopy.en,logo=$('.brand .logo')?.getAttribute('src')||'';
 const star='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 3.5l1.9 5.8 5.8 1.9-5.8 1.9-1.9 5.8-1.9-5.8-5.8-1.9 5.8-1.9z"/><path d="M19 18l.7 1.3L21 20l-1.3.7L19 22l-.7-1.3L17 20l1.3-.7z"/></svg>';
 const shield='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 2.5l8 3.5v5.5c0 5.2-3.4 8.3-8 10-4.6-1.7-8-4.8-8-10V6z"/><path d="M9.5 11.5l1.8 1.8 3.5-3.5"/></svg>';
 return `<section class="auth-screen"><div class="auth-panel"><div class="auth-head"><div class="auth-brand"><img src="${safe(logo)}" alt="AURIX skull symbol"/><span>AURIX</span></div><div class="auth-langs" aria-label="Language">${['en','fr','ar'].map(l=>`<button type="button" data-auth-lang="${l}" class="${lang===l?'active':''}" aria-pressed="${lang===l}">${l.toUpperCase()}</button>`).join('')}</div></div><div class="auth-intro"><h1>${safe(c.welcome)} <em>AURIX</em></h1><p>${safe(c.intro)}</p><div class="auth-facts"><div class="auth-fact">${star}<div><b>${safe(c.caution)}</b><p>${safe(c.cautionText)}</p></div></div><div class="auth-fact">${shield}<div><b>${safe(c.privacy)}</b><p>${safe(c.privacyText)} <a href="#privacy">${safe(c.choices)}</a>.</p></div></div></div></div><div class="auth-actions"><div class="auth-consent">${safe(c.consent)} <a href="#terms">${safe(c.terms)}</a> ${safe(c.and)} <a href="#privacy">${safe(c.policy)}</a>.</div><button class="auth-google" type="button" id="login-google" ${window.AurixCloud?'':'disabled'}><span class="auth-google-mark" aria-hidden="true">G</span><span>${safe(window.AurixCloud?c.google:c.connecting)}</span></button><p class="auth-status" id="login-status" role="alert" aria-live="polite"></p><p class="auth-hint">${safe(c.accountHint)}</p><nav class="auth-public-links" aria-label="Public AURIX guides"><b>Explore AURIX before signing in</b><p>Read practical guides and our site information without an account. Google sign-in is required only for interactive tools.</p><a href="/pages/image-guide.html">Image prompt guide</a><a href="/pages/code-guide.html">Code review guide</a><a href="/pages/writer-guide.html">AI writing guide</a><a href="/pages/about.html">About AURIX</a><a href="/pages/contact.html">Contact</a></nav></div></div></section>`;
}
function home(){const logo=$('.brand .logo')?.getAttribute('src')||'';return `<section class="hero"><p class="hero-eyebrow">YOUR CREATIVE COMMAND CENTER</p><h1 class="sr-only">AURIX AI creative studio</h1><img class="skull" src="${safe(logo)}" alt="AURIX AI emblem with skull"/><p class="hero-title">AURIX <span>AI</span></p><p class="tag">IMAGINE. CREATE. BUILD.</p><p class="sub">One studio for visual ideas, code, and words. Create with real AI models — no demo results, no invented credits.</p><div class="cta"><a class="btn" href="#image">Start creating →</a><a class="btn ghost" href="#code">Explore studios</a></div></section><section aria-label="AI studios"><h2 style="margin:32px 0 0">Tools connected to real providers</h2><div class="tools-grid">${[['image','◈','Image Studio','Turn text into AI-generated visuals.','Real provider'],['code','⌘','Code Studio','Generate, explain and fix code with AI.','Real provider'],['writer','✎','AI Writer','Write, refine and translate with AI.','Real provider'],['video','▷','Video Studio','Text-to-video and image-to-video.','Not available']].map(([r,i,n,d,f],z)=>`<a class="tool-card ${z%2?'v':''}" href="#${r}"><span class="flag ${r==='video'?'off':''}">${f}</span><span class="ic">${$('[data-route="'+r+'"] .nav-icon')?.outerHTML||i}</span><b>${n}</b><p>${d}</p></a>`).join('')}</div></section><div class="feat-strip"><div class="feat"><span style="font-size:22px">◇</span><div><b>No fabricated outputs</b><p>Every result comes from a live provider. Unavailable features say so.</p></div></div><div class="feat"><span style="font-size:22px">⊙</span><div><b>Private by design</b><p>Local work stays in this browser under your account; generation prompts go to the provider.</p></div></div><div class="feat"><span style="font-size:22px">✦</span><div><b>Free, best effort</b><p>Provider limits and availability can change without notice.</p></div></div></div><div class="note warn" style="margin-top:24px">Beta · The authenticated AURIX API and free AI provider are best-effort, with rate limits or outages. Do not enter sensitive information.</div>`}
function chatMessageMarkup(){return chatMessages.length?chatMessages.filter(m=>m&&['user','assistant'].includes(m.role)&&typeof m.text==='string').map(m=>`<div class="chat-line ${m.role==='user'?'user':'assistant'}"><b>${m.role==='user'?'You':'AURIX'}</b><p>${safe(m.text)}</p></div>`).join(''):'<div class="chat-empty"><b>Ask AURIX anything</b><p>Chat about ideas, writing or code. Attach a text-based PDF for document questions. Answers are generated only when the free chat model is configured; no invented replies.</p></div>'}
function chat(){return `${head(t('chat'),'Google sign-in required · your messages stay on this device unless sent to the AI provider for an answer.')}<section class="chat-box"><div class="chat-top"><b>✳ AURIX Chat</b><span class="badge">Free-tier only · best effort</span></div><div class="chat-messages" id="chat-messages" role="log" aria-live="polite">${chatMessageMarkup()}</div><div class="chat-attachment" id="chat-attachment">${chatPdf?`<b>PDF:</b> ${safe(chatPdf.name)} · ${chatPdf.pages} pages ${chatPdf.truncated?'· first 12,000 characters only':''} <button id="chat-remove-pdf" type="button">Remove</button>`:'PDF stays in this browser. Only extracted text is sent when you ask; free-tier requests may be used by the provider to improve services. Maximum 5 MB and 20 pages.'}</div><form id="chat-form"><label class="sr-only" for="chat-input">Your message</label><textarea id="chat-input" class="ta" rows="3" maxlength="2000" minlength="2" required placeholder="Ask AURIX a question about your PDF or another topic…"></textarea><div class="chat-actions"><label class="btn sm ghost chat-attach" for="chat-file">＋ Attach PDF</label><input type="file" id="chat-file" accept="application/pdf,.pdf" hidden/><button class="btn sm" id="chat-send" type="submit">Send →</button></div></form>${state('chat-state')}<p class="hint">Text-based PDFs only; scanned-image PDFs need OCR, which is not configured. AURIX does not upload or save the original PDF.</p></section>`}
function image(){return `${head(t('image'),'Transform a prompt into a real image. A real but rate-limited free image model. Describe exactly what must appear; results are not guaranteed to match.')}
<div class="card"><form id="image-form"><div class="field"><label for="img-prompt">Describe your image</label><textarea id="img-prompt" class="ta" maxlength="600" minlength="4" required placeholder="A floating citadel above an ocean at sunrise, intricate cinematic lighting..." spellcheck="true"></textarea><div class="row" style="margin-top:10px"><button type="button" class="btn sm ghost" id="img-translate">Translate prompt to English (optional)</button><span class="hint">If writing in Arabic or French, review the suggested translation before generating. Uses one text-model request.</span></div></div><div class="field"><label>Optional visual direction · modifies the prompt (not a different model)</label><div class="chips" id="styles">${['As written','Realistic','Cinematic','Anime','Illustration','3D','Fantasy','Minimalist'].map((v,i)=>`<button type="button" class="chip ${i===0?'on':''}" data-style="${v}" aria-pressed="${i===0}">${v}</button>`).join('')}</div></div><div class="field"><label>Aspect ratio</label><div class="chips" id="ratios">${[['Square','1:1']].map(([n,v],i)=>`<button type="button" class="chip ${i===0?'on':''}" data-ratio="${v}" aria-pressed="${i===0}">${n} · ${v}</button>`).join('')}</div></div><div class="field"><label>Generation size</label><div class="chips" id="qualities"><button type="button" class="chip on" data-quality="fast" aria-pressed="true">Fast · 4 steps</button><button type="button" class="chip" data-quality="detail" aria-pressed="false">Detail · 8 steps</button></div></div><div class="row"><button class="btn" id="img-go" type="submit">◈ &nbsp; Generate image</button><span class="hint">Cloudflare Workers AI · square images · daily free allowance on Workers Free.</span></div></form>${state('img-state')}<div id="img-result"></div></div><div class="note info" style="margin-top:16px">Your prompt is processed by Cloudflare Workers AI using FLUX.1 Schnell. Free usage depends on the Workers Free daily allocation and may stop when exhausted. It currently creates square images only. This model may miss details; verify every image. New images are saved only on this device in your browser image storage, not in Firestore. Download copies you want to keep. Older image entries may still contain provider links.</div><h2 style="margin-top:28px">Image gallery</h2><div id="img-gallery" class="img-grid">${imageCards(items.filter(o=>o.kind==='image').slice(0,12))}</div>`}
function imageCards(list){return list.length?list.map(o=>`<article class="img-card"><img loading="lazy" ${imageMarkup(o)} alt="AI image: ${safe(o.prompt.slice(0,80))}"/><div class="bar"><span class="ttl" title="${safe(o.prompt)}">${safe(o.prompt)}</span><button class="icon-btn fav ${o.fav?'on':''}" data-fav="${safe(o.id)}" aria-label="Toggle favorite">♥</button><button class="icon-btn" data-download="${safe(o.id)}" aria-label="Download image">↓</button></div></article>`).join(''):`<div class="empty" style="grid-column:1/-1"><b>No images yet</b>Generate your first image above.</div>`}
function video(){return `${head(t('video'),'Real video generation only — no simulated videos or fake progress.')}
<div class="card" style="text-align:center;padding:50px 24px"><div style="font-size:58px;color:var(--violet2)">▷</div><h2 style="display:block;margin:15px 0">${t('unavailable')}</h2><p style="color:var(--muted);max-width:560px;margin:0 auto 18px">Text-to-video and image-to-video are disabled. We have not configured a provider with a verified sustainable quota and usage rights. No video is being generated here.</p><div class="note info" style="max-width:560px;margin:auto;text-align:start">When a genuine provider is configured and tested, supported duration, aspect ratio, progress and downloads can be added. We will not show controls that cannot work.</div></div>`}
const codeTasks={generate:'Generate code',explain:'Explain code',fix:'Fix errors',improve:'Improve code',component:'Website component'};
function code(){return `${head(t('code'),'Generate and understand code with a real text model. Always review and test generated code before production.')}
<div class="card"><form id="code-form"><div class="field"><label for="code-task">Action</label><select class="input" id="code-task">${Object.entries(codeTasks).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></div><div class="field"><label for="code-lang">Language / format</label><select class="input" id="code-lang"><option>HTML/CSS/JavaScript</option><option>JavaScript</option><option>HTML</option><option>CSS</option><option>Python</option><option>Other</option></select></div><div class="field"><label for="code-prompt">Describe what you need or paste code</label><textarea class="ta" id="code-prompt" minlength="5" maxlength="3500" required style="min-height:150px" placeholder="Build a responsive pricing card using HTML and CSS..."></textarea></div><button class="btn" type="submit" id="code-go">⌘ &nbsp; Ask AI</button></form>${state('code-state')}<div id="code-result" hidden><div class="out-head"><h3>Model output · verify before use</h3><button type="button" class="btn sm ghost" id="code-copy">Copy</button><button type="button" class="btn sm ghost" id="code-save">Save snippet</button><button type="button" class="btn sm ghost" id="code-download">Download .txt</button></div><div class="code-out"><pre><code id="code-text"></code></pre></div><div class="row" style="margin-top:14px"><label style="color:var(--muted);font-size:13px"><input type="checkbox" id="preview-check"/> I understand that running generated HTML/JS can be risky; show isolated preview</label></div><div id="preview-area" hidden><iframe class="preview-frame" id="preview-frame" sandbox="allow-scripts" referrerpolicy="no-referrer" title="Isolated code preview"></iframe><p class="hint">Only HTML documents can be previewed; sandboxed frame has no same-origin access. Untrusted code may still contact external sites; never run sensitive code.</p></div></div></div><div class="note warn" style="margin-top:16px">AI-generated code can contain bugs and security flaws. Never paste credentials. Your request and any pasted code are sent to Pollinations.ai for processing.</div>`}
const writerTasks={article:['Article or website copy','Write detailed, original content for a specified audience'],caption:['Social caption','Create platform-ready social captions'],product:['Product description','Describe product benefits clearly'],rewrite:['Rewrite','Improve clarity while preserving meaning'],summary:['Summarize','Create a concise, accurate summary'],grammar:['Grammar','Correct spelling and grammar'],translate:['Translate','Translate into a specified language'],prompt:['Creative prompt','Craft a prompt for an image/video model']};
function writer(){return `${head(t('writer'),'Real AI writing and editing. Provide context and verify factual claims yourself.')}
<div class="card"><div class="field"><label>Choose an action</label><div class="tools-list" id="writer-tasks">${Object.entries(writerTasks).map(([k,[n,d]],i)=>`<button type="button" class="tool-opt ${i===0?'on':''}" data-wtask="${k}" aria-pressed="${i===0}"><b>${n}</b><small>${d}</small></button>`).join('')}</div></div><form id="writer-form"><div class="field"><label for="writer-prompt">Topic, instructions, or source text</label><textarea class="ta" id="writer-prompt" minlength="5" maxlength="3500" required placeholder="Write an introduction to sustainable packaging for small shops..."></textarea></div><div class="field"><label for="writer-lang">Output language</label><select class="input" id="writer-lang"><option>English</option><option>French</option><option>Arabic</option></select></div><button class="btn" type="submit" id="writer-go">✎ &nbsp; Generate text</button></form>${state('writer-state')}<div id="writer-result" hidden><div class="out-head"><h3>AI-generated output · verify facts</h3><button type="button" class="btn sm ghost" id="writer-copy">Copy</button><button type="button" class="btn sm ghost" id="writer-save">Save to projects</button><button type="button" class="btn sm ghost" id="writer-download">Download .txt</button></div><div class="writer-out" id="writer-text"></div></div></div><div class="note info" style="margin-top:16px">Requests are sent to Pollinations.ai; avoid personal or confidential data. Generated text is not guaranteed to be factual, original or suitable for publication without editing.</div>`}
function entry(o){return `<article class="hist-card">${o.kind==='image'?`<div class="thumb"><img loading="lazy" ${imageMarkup(o)} alt="Generated image"/></div>`:''}<span class="kind k-${safe(o.kind)}">${safe(o.kind)}</span><b>${safe(o.prompt.slice(0,68))}</b><p>${o.kind==='image'?safe(o.meta?.style||'AI image'):safe(o.result.slice(0,200))}</p><time datetime="${safe(o.at)}">${safe(fmt(o.at))}</time><div class="row"><button class="btn sm ghost" type="button" data-fav="${safe(o.id)}">${o.fav?'♥ Favorited':'♡ Favorite'}</button>${o.kind==='image'?`<button class="btn sm ghost" data-download="${safe(o.id)}">↓ Download</button>`:`<button class="btn sm ghost" data-copy-item="${safe(o.id)}">Copy</button>`}${window.AurixCloud?.user&&!o.result?.startsWith(PHOTO)?`<button class="btn sm ghost" data-cloud-save="${safe(o.id)}">☁ Save to cloud</button>`:''}<button class="btn sm ghost" data-delete="${safe(o.id)}" aria-label="Remove saved item">×</button></div><label class="hint">Folder <select class="input" data-move="${safe(o.id)}" style="margin-top:4px">${folders.map(f=>`<option ${o.folder===f?'selected':''}>${safe(f)}</option>`).join('')}</select></label></article>`}
function history(){return `${head(t('history'),'Your recent generations are saved only in this browser. Clearing browser data removes them.')}<div class="row"><button type="button" class="btn sm ghost" id="export-items">↓ Export all as JSON</button></div><div class="hist-grid">${items.length?items.map(entry).join(''):'<div class="empty" style="grid-column:1/-1"><b>No history yet</b>Your real generations will appear here.</div>'}</div>`}
function favorites(){const a=items.filter(o=>o.fav);return `${head(t('favorites'),'Favorite items saved in your browser.')}<div class="hist-grid">${a.length?a.map(entry).join(''):'<div class="empty" style="grid-column:1/-1"><b>No favorites</b>Select the heart on a creation.</div>'}</div>`}
function projects(){return `${head(t('projects'),'Local folders stay on this device; only projects you choose are copied to your cloud account.')}
<div class="card"><form id="folder-form" class="row"><label for="folder-name" style="width:100%;font-weight:700">New folder</label><input id="folder-name" class="input" maxlength="42" required style="flex:1;min-width:180px" placeholder="My experiments"/><button class="btn sm" type="submit">+ Create folder</button></form></div><div class="proj-folders">${folders.map(f=>`<div class="card" style="padding:16px"><b>▣ &nbsp;${safe(f)}</b><p class="hint">${items.filter(o=>o.folder===f).length} saved items</p></div>`).join('')}</div><div class="hist-grid">${items.length?items.map(entry).join(''):'<div class="empty" style="grid-column:1/-1"><b>No projects yet</b>Generate and save work to organize it here.</div>'}</div>${window.AurixCloud?.user?'<div class="card" style="margin-top:20px"><h2>Cloud projects</h2><p class="hint">Saved only when you click Save to cloud. Each account sees its own records.</p><div id="cloud-items" aria-live="polite">Loading saved projects…</div></div>':''}`}
function settings(){return `${head(t('settings'),'Your AURIX account is active. Cloud saving remains your choice.')}
<div class="card"><h2>Privacy &amp; local data</h2><div class="set-grid"><div class="set-tile"><b>Export your work</b><p>Save prompts, text outputs and metadata as JSON. Locally stored images are NOT embedded in this export; download them separately.</p><button class="btn sm ghost" id="export-items">Download JSON</button></div><div class="set-tile"><b>Delete local data</b><p>Remove this account’s local history, favorites, projects and folders from this browser. This cannot be undone.</p><button class="btn sm ghost" id="clear-data">Clear AURIX data</button></div><div class="set-tile"><b>Accounts</b>${window.AurixCloud?(window.AurixCloud.user?`<p>Signed in as ${safe(window.AurixCloud.user.email||'Google user')}. Only items explicitly saved to cloud are synced.</p><button class="btn sm ghost" type="button" id="google-signout">Sign out</button><button class="btn sm ghost" type="button" id="google-delete" style="margin-top:8px">Delete account and cloud items</button>`:'<p>Google sign-in is available. Google sign-in is required to enter.</p><button class="btn sm" type="button" id="google-signin">Sign in with Google</button>'):'<p>Google sign-in is unavailable. Please retry later.</p>'}</div></div></div><div class="note warn" style="margin-top:16px">AURIX cannot remove data sent to the external provider on your behalf. Consult the provider's privacy policy for its retention and deletion process.</div>`}
function info(title,content){return `<div class="aurix-page"><h1>${title}</h1><div class="card content">${content}</div></div>`}
function about(){return info('About AURIX',`<p><strong>AURIX — Imagine. Create. Build.</strong> is an independent creative workspace for images, coding help and writing. It is currently an early-stage site hosted on Firebase Hosting for staging, with a separate Blogger theme available.</p><h2>What works today</h2><p>Signed-in requests pass through the AURIX Cloudflare Worker, which calls Cloudflare Workers AI for images and Pollinations.ai for text. Video generation is not active. ${window.AurixCloud?'Google sign-in is required to use the interactive studio; explicit cloud saves are available.':'User accounts and cloud sync are not active.'} There are no ads at launch.</p><h2>How we build trust</h2><p>We do not simulate model responses, fake quota balances or show pretend generation progress. Free provider availability can change. Always check the results before use, especially code and factual writing.</p><h2>Brand</h2><p>The AURIX skull artwork is based on the project owner’s supplied reference image. AURIX is not affiliated with Pollinations.ai.</p>`)}
function contact(){return info('Contact',`<p>For questions, feedback or privacy requests, email <a href="mailto:ahmedbecetti41@gmail.com">ahmedbecetti41@gmail.com</a>. Your email application will open; this website does not submit your message itself.</p><p><strong>Site address:</strong> <a href="https://skullaistudio.blogspot.com/">skullaistudio.blogspot.com</a></p><p class="note info">Please allow time for a reply. Do not include passwords or API keys in email.</p>`)}
function privacy(){return info('Privacy Policy',`<p><strong>Last updated: October 24, 2026.</strong> This policy describes the current AURIX application, including Google sign-in, on its staging domain. It will be updated when features change.</p><h2>Information you provide</h2><p>When you generate images, your prompt is processed through the authenticated Cloudflare Worker by Cloudflare Workers AI using FLUX.1 Schnell (Black Forest Labs). Text/code requests are sent by the Worker to Pollinations.ai. Do not submit private information; each provider's terms and privacy practices apply. For chat, typed messages and text extracted locally from an attached PDF are sent to the AURIX Worker and then to Google Gemini when the free-tier model is configured; the original PDF is not uploaded. Do not submit passwords, secrets, confidential documents or personal data.</p><h2>Local browser data</h2><p>History, recent chat messages, saved text, prompts, favorites, folders and your language preference are saved in this browser’s storage. New image bytes are stored in this browser’s IndexedDB under your account, not in exported JSON or Firestore. Older entries may contain external provider links. You can export or erase this data under Settings. Locally saved projects are stored by account on this browser. Clearing browser data deletes them.</p><h2>Third-party services</h2><p>Firebase Hosting (Google) hosts this staging site and may set cookies and collect technical information under its own privacy terms. Cloudflare processes authenticated API requests; Cloudflare Workers AI processes image prompts, Pollinations.ai receives text/code generation prompts, and Gemini receives chat messages plus extracted PDF text from the Worker and may log request data. Existing older image links may contact Pollinations.ai directly. This site does not currently enable advertising or a separate analytics service.</p><h2>Security and retention</h2><p>${window.AurixCloud?'Google sign-in is required for the studio; Firebase Authentication processes your account identity and Google email; projects you explicitly save to cloud are stored in Cloud Firestore under your user ID. You can delete your account and its saved cloud projects in Settings.':'We do not operate an account database in this version.'} Browser storage is not encrypted or suitable for confidential information. Firebase Authentication checks Google sign-in; the staging website’s static files remain publicly accessible. The owner's control over third-party provider retention is limited. See the provider’s policy for its own deletion requests.</p><h2>Questions</h2><p>See <a href="#contact">Contact</a>. Email <a href="mailto:ahmedbecetti41@gmail.com">ahmedbecetti41@gmail.com</a> for site questions and privacy requests.</p>`)}
function terms(){return info('Terms of Service',`<p><strong>Last updated: October 24, 2026.</strong> By using AURIX you agree to use it lawfully and responsibly. This early-stage service is provided as available, without a guaranteed uptime or free quota.</p><h2>AI-generated material</h2><p>Outputs may be inaccurate, unsafe, infringing or unsuitable for your purpose. You are responsible for reviewing them. Generated code must be tested and audited before production. AURIX does not guarantee output originality, ownership or commercial-use rights.</p><h2>Provider availability</h2><p>Active features depend on Cloudflare Workers AI for images, Pollinations.ai for text, and applicable provider and model terms. Access, limits and supported features may change or stop at any time. Video generation is not offered in this version. ${window.AurixCloud?'Google sign-in and optional cloud saving are governed by Google/Firebase terms; account deletion is in Settings.':'Account features are not offered.'}</p><h2>Acceptable use</h2><p>Do not submit harmful, illegal or unauthorized content, third-party secrets or personal information without permission. Do not attempt automated abuse or bypass provider limits.</p><h2>Local data</h2><p>Local project data is stored by account in your browser. You are responsible for exporting it if needed. AURIX cannot restore cleared local storage.</p><h2>External terms</h2><p>Your use of Cloudflare Workers AI and Black Forest Labs FLUX models for images and Pollinations.ai for text is subject to applicable terms and policies. The staging site is hosted by Firebase Hosting; a Blogger theme is available separately. Google hosting terms apply. See <a href="#privacy">Privacy Policy</a>.</p>`)}
function toggleChips(selector,attr){$$(selector+' [data-'+attr+']').forEach(b=>b.addEventListener('click',()=>{$$(selector+' [data-'+attr+']').forEach(c=>{c.classList.remove('on');c.setAttribute('aria-pressed','false')});b.classList.add('on');b.setAttribute('aria-pressed','true')}))}
function downloadBlob(blob,name){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}
function downloadText(text,name,mime='text/plain'){downloadBlob(new Blob([text],{type:mime}),name)}
async function downloadImg(o){try{if(o.result.startsWith(PHOTO)){const blob=await photoGet(o.id);if(!blob)throw Error('Image not found on this device');downloadBlob(blob,'aurix-'+o.id+'.jpg');return}const res=await fetch(o.result);if(!res.ok||!res.headers.get('content-type')?.startsWith('image/'))throw Error('Legacy image no longer available');downloadBlob(await res.blob(),'aurix-'+o.id+'.jpg')}catch(e){toast(e.message||'Image download failed.','err')}}
function textError(res,body){
  const wait=Number.parseInt(res.headers?.get('Retry-After')||'',10);
  if(res.status===402||res.status===429||res.headers?.get('Retry-After'))return `Free provider limit reached. ${Number.isFinite(wait)?`Try again in about ${wait} seconds.`:'Wait and try later.'} Image generation may have exhausted the Workers AI daily free allowance on this account.`;
  let message=String(body||'').slice(0,180);
  try{const parsed=JSON.parse(body);message=parsed.error?.message||parsed.message||message}catch{}
  return `Provider error (${res.status}). ${message||'Please try again later.'}`;
}
const cooldown={text:30000,image:45000};
function checkRate(kind){let at=Number(localStorage.getItem(key('last_'+kind))||0),left=cooldown[kind]-(Date.now()-at);if(left>0)throw Error(`Please wait ${Math.ceil(left/1000)} seconds before another ${kind} request. The provider may require longer.`);localStorage.setItem(key('last_'+kind),String(Date.now()))}
async function apiRequest(kind,payload,signal){
  const cloud=window.AurixCloud;
  if(!cloud?.user||!cloud.getIdToken)throw Error('Sign in with Google to use AURIX.');
  const token=await cloud.getIdToken();
  if(signal?.aborted)throw new DOMException('Request aborted','AbortError');
  if(!cloud.user)throw Error('You have signed out. Sign in again.');
  let response;
  try{response=await fetch(API+'/api/'+kind,{method:'POST',headers:{'Authorization':'Bearer '+token,'Content-Type':'application/json'},body:JSON.stringify(payload),signal,referrerPolicy:'no-referrer'})}
  catch(e){if(e.name==='AbortError')throw e;throw Error('Secure AURIX API is unreachable. Please try again later.')}
  if(response.status===401)throw Error('Your Google session expired. Sign out and sign in again.');
  return response;
}

function beginJob(st,button,message,limitSeconds){
  const controller=new AbortController(),started=Date.now();busy=true;button.disabled=true;
  showState(st,'loading',message);
  const elapsed=document.createElement('span');elapsed.className='hint';elapsed.style.display='block';elapsed.setAttribute('aria-hidden','true');st.querySelector('.msg').append(elapsed);
  const cancel=document.createElement('button');cancel.type='button';cancel.className='btn sm ghost';cancel.textContent='Cancel';cancel.setAttribute('aria-label','Cancel request');st.append(cancel);
  cancel.onclick=()=>controller.abort('cancelled');
  const tick=setInterval(()=>{elapsed.textContent=`${Math.floor((Date.now()-started)/1000)}s elapsed · maximum ${limitSeconds}s`;},1000);
  const timeout=setTimeout(()=>controller.abort('timeout'),limitSeconds*1000);
  activeJob={controller,tick,timeout};return activeJob;
}
function finishJob(job,button){clearTimeout(job.timeout);clearInterval(job.tick);button.disabled=false;if(activeJob===job){activeJob=null;busy=false}}
function jobError(e,job){if(e.name==='AbortError')return job.controller.signal.reason==='timeout'?'The provider took too long; the request was stopped. Try again later or use a shorter prompt.':'Request cancelled. No result was saved.';return e.message||'The provider is unavailable. Try again later.'}
async function getText(prompt,signal){
  if(!window.AurixCloud?.user)throw Error('Sign in with Google to use AURIX.');
  checkRate('text');const res=await apiRequest('text',{prompt},signal);
  const contentType=res.headers.get('content-type')||'';
  const body=(contentType.startsWith('text/')||contentType.includes('json'))?await res.text():'';
  if(!res.ok)throw Error(textError(res,body));
  if(!body.trim())throw Error('The provider returned an empty response. Please retry later.');
  return body.trim();
}
async function looksLikeLimitCard(blob){
  if(typeof createImageBitmap!=='function')return false;
  try{
    const bitmap=await createImageBitmap(blob),canvas=document.createElement('canvas');canvas.width=bitmap.width;canvas.height=bitmap.height;
    const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(bitmap,0,0);bitmap.close();
    const pixel=(x,y)=>[...ctx.getImageData(Math.floor(canvas.width*x),Math.floor(canvas.height*y),1,1).data];
    const yellow=(v)=>v[0]>235&&v[1]>190&&v[1]<240&&v[2]>75&&v[2]<145;
    const corners=[[.02,.02],[.98,.02],[.02,.98],[.98,.98]];
    return corners.every(([x,y])=>yellow(pixel(x,y)))&&pixel(.1,.4)[0]<90;
  }catch{return false}
}
async function getImage(prompt,style,ratio,quality,signal){
  if(!window.AurixCloud?.user)throw Error('Sign in with Google to use AURIX.');
  checkRate('image');
  // As written means do not silently rewrite a user's description.
  const q=style==='As written'?prompt:`${prompt}. Visual style: ${style}.`;
  const r=await apiRequest('image',{prompt:q,ratio,quality},signal);
  if(r.status===502||r.status===503)throw Error('Image generation is temporarily unavailable: the free provider failed. No image was created or saved. Please try later.');
  if(!r.ok||r.headers.get('Retry-After'))throw Error(textError(r, r.headers.get('content-type')?.includes('json')?await r.text():''));
  if(!r.headers.get('content-type')?.startsWith('image/'))throw Error('The provider did not return an image.');
  const blob=await r.blob();
  if(blob.size<3000)throw Error('The provider returned an incomplete image. No result was saved.');
  const sig=new Uint8Array(await blob.slice(0,3).arrayBuffer());
  if(!(sig[0]===0xff&&sig[1]===0xd8&&sig[2]===0xff))throw Error('The provider returned an unexpected file instead of a JPEG image.');
  return {blob};
}
function syntax(s){let parts=String(s).split(/(\/\/[^\n]*|\/\*[\s\S]*?\*\/|<!--[\s\S]*?-->|"(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'|`(?:[^`\\]|\\.)*`|\b(?:const|let|var|function|return|if|else|class|import|export|async|await|def|for|while|new|try|catch|throw|true|false|null|undefined)\b|\b\d+(?:\.\d+)?\b|<\/?[A-Za-z][\w-]*)/g);return parts.map(p=>{let e=safe(p);if(/^(\/\/|\/\*|<!--)/.test(p))return '<span class="tk-com">'+e+'</span>';if(/^["'`]/.test(p))return '<span class="tk-str">'+e+'</span>';if(/^<\/?[A-Za-z]/.test(p))return '<span class="tk-tag">'+e+'</span>';if(/^\d/.test(p))return '<span class="tk-num">'+e+'</span>';if(/^(const|let|var|function|return|if|else|class|import|export|async|await|def|for|while|new|try|catch|throw|true|false|null|undefined)$/.test(p))return '<span class="tk-kw">'+e+'</span>';return e}).join('')}
