 if(route==='projects'){if($('#cloud-items'))window.AurixCloud.list().then(a=>{cloudItems=a;$('#cloud-items').innerHTML=a.length?a.map(o=>`<div class="hist-card" style="margin-top:10px"><b>${safe((o.prompt||'Untitled').slice(0,90))}</b><small>${safe(o.kind)} · ${safe(o.at||'')}</small><p>${safe((o.result||'').slice(0,230))}</p><button type="button" class="btn sm ghost" data-cloud-import="${safe(o.id)}">Restore to this browser</button><button type="button" class="btn sm ghost" data-cloud-remove="${safe(o.id)}">Delete cloud copy</button></div>`).join(''):'No cloud projects yet.'}).catch(e=>{$('#cloud-items').textContent='Could not load cloud projects: '+e.message});$('#folder-form').addEventListener('submit',e=>{e.preventDefault();let f=$('#folder-name').value.trim();if(f&&!folders.some(x=>x.toLowerCase()===f.toLowerCase())){folders.push(f);save('folders',folders);render()}else toast('Folder already exists or name is empty.','err')})}
